Skinned = AddSkinCachePass(SourceVertices, BoneTransforms);

Refined = CreateBuffer(RefinedVertexCount);
AddComputePass(
    /* reads  */ Skinned.Positions, StencilOffsets,
                 StencilSizes, StencilIndices, StencilWeights,
    /* writes */ Refined.Positions);

SubmitMeshBatch(/* vertex stream */ Refined.Positions);

for (uint32 i = 0; i < stencilCount; ++i) {
    Vec3 value = Vec3(0);
    const uint32 begin = offsets[i];
    const uint32 end = begin + sizes[i];

    for (uint32 k = begin; k < end; ++k)
        value += weights[k] * control[indices[k]];

    output[i] = value;
}

StructuredBuffer<uint>   Sizes;
StructuredBuffer<uint>   Offsets;
StructuredBuffer<uint>   ControlIndices;
StructuredBuffer<float>  Weights;
StructuredBuffer<float3> ControlPositions;
RWStructuredBuffer<float3> OutputPositions;

cbuffer Params { uint StencilCount; uint OutputBase; };

[numthreads(64, 1, 1)]
void MainCS(uint3 dispatchId : SV_DispatchThreadID)
{
    uint i = dispatchId.x;
    if (i >= StencilCount) return;

    uint begin = Offsets[i];
    uint end = begin + Sizes[i];
    float3 p = 0.0;
    for (uint k = begin; k < end; ++k)
        p += Weights[k] * ControlPositions[ControlIndices[k]];

    OutputPositions[OutputBase + i] = p;
}

